 x=np.zeros((1024,1024),bool);r,c=z['mask_bbox'];h,w=z['mask'].shape;x[r:r+h,c:c+w]=z['mask']>=128;m.append(x)
T=cv2.cvtColor(s.target_image(),cv2.COLOR_RGB2GRAY)<100;D=cv2.distanceTransform((~T).astype(np.uint8),cv2.DIST_L2,3);F=D>4.51;tc=T.sum(); shifts=np.zeros((N,2),int)
def shift(src,dx,dy):
 o=np.zeros_like(src); y0=max(0,-dy);y1=min(1024,1024-dy);x0=max(0,-dx);x1=min(1024,1024-dx);o[y0+dy:y1+dy,x0+dx:x1+dx]=src[y0:y1,x0:x1];return o
for i in range(N):
 base=np.logical_or.reduce([m[j] for j in range(N) if j!=i]);bc=int(base.sum());bi=int((base&T).sum());bs=int((base&F).sum());bf=base.ravel();tf=T.ravel();ff=F.ravel();y,x=np.nonzero(m[i]);best=(-1e9,0,0,0,0)
 for dy in range(-12,13):
  yy=y+dy;vy=(yy>=0)&(yy<1024)
  for dx in range(-12,13):
