   if obj>best[0]:best=(obj,dx,dy,iou,stray)
 _,dx,dy,ii,ss=best;shifts[i]=[dx,dy];m[i]=shift(m[i],dx,dy);print(i+1,dx,dy,round(ii,4),round(ss,4),flush=True)
own=np.logical_or.reduce(m);print('offsets',shifts.tolist());print('metrics',int(own.sum()),float((own&T).sum()/(own|T).sum()),float((own&F).sum()/tc))
